import{_ as s,c as i,o as a,a9 as n}from"./chunks/framework.Bqk8xQPS.js";const k=JSON.parse('{"title":"Knowledge & RAG","description":"Deep dive into the vector stores, document adapters and multi-tenant scoping.","frontmatter":{"title":"Knowledge & RAG","description":"Deep dive into the vector stores, document adapters and multi-tenant scoping.","order":299907},"headers":[],"relativePath":"handbook/2_building_business-logic/advanced/ai-knowledge.md","filePath":"handbook/2_building_business-logic/advanced/ai-knowledge.md","lastUpdated":1773353649000}'),t={name:"handbook/2_building_business-logic/advanced/ai-knowledge.md"};function l(d,e,o,r,p,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="ai-knowledge-rag-advanced-view" tabindex="-1">AI Knowledge &amp; RAG (Advanced View) <a class="header-anchor" href="#ai-knowledge-rag-advanced-view" aria-label="Permalink to “AI Knowledge &amp; RAG (Advanced View)”">​</a></h1><p>Retrieval-Augmented Generation (RAG) is a technique for grounding an LLM&#39;s answers in your specific data. PURISTA&#39;s <code>KnowledgeAdapter</code> system is designed to handle this while respecting multi-tenancy and security.</p><h2 id="_1-the-knowledge-architecture" tabindex="-1">1. The Knowledge Architecture <a class="header-anchor" href="#_1-the-knowledge-architecture" aria-label="Permalink to “1. The Knowledge Architecture”">​</a></h2><p>In PURISTA, knowledge is not just a vector database. It is a system that automatically handles <strong>scoping</strong>.</p><p>When you query knowledge in a handler:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> docs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> context.knowledge.supportFaq.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(payload.prompt, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The query is automatically scoped by:</p><ul><li><code>tenantId</code> (Multi-tenancy separation)</li><li><code>principalId</code> (User separation)</li><li><code>agentName</code> and <code>agentVersion</code> (Agent-level separation)</li><li><code>sessionId</code> (Conversation separation)</li></ul><p>This ensures that one user&#39;s private data is never &quot;leaked&quot; to another user&#39;s LLM prompt.</p><h2 id="_2-multi-tenant-scoping" tabindex="-1">2. Multi-tenant Scoping <a class="header-anchor" href="#_2-multi-tenant-scoping" aria-label="Permalink to “2. Multi-tenant Scoping”">​</a></h2><p>The scope is automatically resolved by the agent runtime before calling the adapter. This means your adapter implementation can focus on the storage-specific filtering logic:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">async </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(request: KnowledgeQueryRequest): </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Promise</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KnowledgeDocument[]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  const { query, limit, scope } = request</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // scope contains tenantId, principalId, agentName, agentVersion, sessionId</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  return this.vectorDb.search(query, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    limit,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      tenantId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: scope.tenantId,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      principalId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: scope.principalId,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      agentName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: scope.agentName,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      agentVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: scope.agentVersion,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      sessionId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: scope.sessionId,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="_3-knowledge-lifecycle" tabindex="-1">3. Knowledge Lifecycle <a class="header-anchor" href="#_3-knowledge-lifecycle" aria-label="Permalink to “3. Knowledge Lifecycle”">​</a></h2><p>Knowledge is typically managed in three stages:</p><ol><li><strong>Ingestion</strong>: Adding new documents to the store via <code>context.knowledge.&lt;alias&gt;.upsert()</code>.</li><li><strong>Retrieval</strong>: Querying documents in the agent handler via <code>context.knowledge.&lt;alias&gt;.query()</code>.</li><li><strong>Context Injection</strong>: Combining the retrieved documents with the user prompt before calling the model.</li></ol><h2 id="_4-advanced-adapter-patterns" tabindex="-1">4. Advanced Adapter Patterns <a class="header-anchor" href="#_4-advanced-adapter-patterns" aria-label="Permalink to “4. Advanced Adapter Patterns”">​</a></h2><p>For complex data sources, you can implement custom adapters that:</p><ul><li>Pre-process documents (e.g., chunking, metadata extraction).</li><li>Use specific embedding models.</li><li>Handle fallback or hybrid search (vector + keyword).</li></ul><p>See the <strong><a href="./ai-custom-stores.html">Custom AI Stores</a></strong> section for implementation details.</p>`,19)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
